-- V-L15 (run O1, session.sh J4 and J5): after L15-A2-series-games.sql, the facts of the two games of one series.
-- Read only, in a read-only transaction. Each row is: ok or KO | what | the number found. Never a name, an e-mail, a target or a row of a person.
-- The pools are information, not a gate: L15 holds the characters L04 has, the others wait for the L04 regeneration, and a game under its minimum stays off (L14).
begin transaction read only;
select case when ok is true then 'ok' else 'KO' end, what, coalesce(got, '-') from (values
  (1, 'faits : chaque ligne appartient à la série de son jeu', (select count(*) = 0 from public.character_game_facts f join public.characters c on c.id = f.character_id join public.groups g on g.id = c.group_id where not ((f.game_id = 'otakudle-one-piece' and g.slug = 'one-piece') or (f.game_id = 'otakudle-dragon-ball' and g.slug = 'dragon-ball'))), (select count(*)::text from public.character_game_facts)),
  (2, 'faits de personnages hors du pool (brouillon, identité cachée) : information', true, (select count(*)::text from public.character_game_facts f join public.characters c on c.id = f.character_id where c.status <> 'published' or c.identity_spoiler)),
  (3, 'valeurs sans source : 0', (select count(*) = 0 from public.character_game_facts f join public.characters c on c.id = f.character_id join public.groups g on g.id = c.group_id, lateral jsonb_each(f.attrs) a(key, val) where jsonb_typeof(a.val -> 'v') not in ('null') and a.val -> 'v' is not null and not exists (select 1 from public.entity_sources s where s.entity_type = 'character' and s.entity_id = c.slug and s.field = g.slug || '.' || a.key)), null),
  (4, 'indices sans source : 0', (select count(*) = 0 from public.character_game_facts f join public.characters c on c.id = f.character_id join public.groups g on g.id = c.group_id, lateral jsonb_each(f.hints) h(key, val) where not exists (select 1 from public.entity_sources s where s.entity_type = 'character' and s.entity_id = c.slug and s.field = g.slug || '.' || h.key)), null),
  (5, 'sources : seulement wikidata, wikipedia, fandom, avec une adresse', (select count(*) = 0 from public.entity_sources s where s.entity_type = 'character' and s.field ~ '^(one-piece|dragon-ball)[.]' and (s.source not in ('wikidata', 'wikipedia', 'fandom') or s.source_url !~ '^https://')), (select count(*)::text from public.entity_sources s where s.entity_type = 'character' and s.field ~ '^(one-piece|dragon-ball)[.]')),
  (6, 'une cible a toutes les colonnes de son jeu', (select count(*) = 0 from public.character_game_facts f join public.dle_attributes a on a.game_id = f.game_id where f.can_be_target and coalesce(cardinality(public.dle_values(f.attrs -> a.key -> 'v')), 0) = 0), null),
  (7, 'une cible a son indice de 5 erreurs (One Piece : fruit ou aucun fruit ; Dragon Ball : technique ou doubleur)', (select count(*) = 0 from public.character_game_facts f where f.can_be_target and not (case f.game_id when 'otakudle-one-piece' then f.attrs -> 'devil_fruit_type' ->> 'v' = 'none' or nullif(btrim(f.hints ->> 'devil_fruit_name'), '') is not null else nullif(btrim(f.hints ->> 'signature_technique'), '') is not null or nullif(btrim(f.hints ->> 'voice_actor_ja'), '') is not null end)), null),
  (8, 'One Piece : cibles dans la vue, minimum et état (information)', true, (select (select count(*) from public.dle_src_otakudle_one_piece where can_be_target) || ' cibles, minimum ' || coalesce((select min_pool::text from public.dle_games where id = 'otakudle-one-piece'), '40') || ', ' || coalesce((select case when active then 'allumé' else 'éteint' end from public.dle_games where id = 'otakudle-one-piece'), 'jeu absent'))),
  (9, 'Dragon Ball : cibles dans la vue, minimum et état (information)', true, (select (select count(*) from public.dle_src_otakudle_dragon_ball where can_be_target) || ' cibles, minimum ' || coalesce((select min_pool::text from public.dle_games where id = 'otakudle-dragon-ball'), '30') || ', ' || coalesce((select case when active then 'allumé' else 'éteint' end from public.dle_games where id = 'otakudle-dragon-ball'), 'jeu absent')))
) as c(n, what, ok, got) order by n;
rollback;
